class GymMember{protected String memberId;protected int monthlyFee;private int sessionsAttended;GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException();memberId=id;monthlyFee=fee;}void attendSession(){sessionsAttended++;}int getSessionsAttended(){return sessionsAttended;}String displayInfo(){return "Standard Member | Sessions: "+sessionsAttended;}static String signUpBatch(String[] ids,int fee){int ok=0,bad=0;for(String id:ids)try{new GymMember(id,fee);ok++;}catch(IllegalArgumentException e){bad++;}return "Signed Up: "+ok+" | Rejected: "+bad;}protected void chargeLateFee(int amount){if(fineCount>=fineHistory.length)throw new IllegalStateException();fineHistory[fineCount++]=amount;}private int[] fineHistory=new int[10];private int fineCount;int[] getLateFeeHistory(){return java.util.Arrays.copyOf(fineHistory,fineCount);}int getTotalLateFees(){int s=0;for(int i=0;i<fineCount;i++)s+=fineHistory[i];return s;}}
class PremiumMember extends GymMember{String trainerName;PremiumMember(String id,int fee,String trainer){super(id,fee);trainerName=trainer;}String displayInfo(){return "Premium Member | Trainer: "+trainerName+" | Sessions: "+getSessionsAttended();}@Override protected void chargeLateFee(int amount){super.chargeLateFee(amount/2);}}
public class Main{public static void main(String[]a){PremiumMember p=new PremiumMember("MEM01",2000,"Coach Riya");p.attendSession();p.attendSession();System.out.println(p.getSessionsAttended());System.out.println(GymMember.signUpBatch(new String[]{"MEM1","GM1","MEM2"," ","MEM3"},1000));}}